    const syntax = `infographic list-waterfall-badge-card
data
  title WEB SUMMIT LISBON 2026
  desc November 9–12 · Lisbon, Portugal · Where the Future Meets Now
  lists
    - label 2-FOR-1 TICKET SALE
      value 50%
      desc SAVE 50% · 24 HOURS ONLY · Buy one, get one free — act now before this offer expires
      icon ticket
    - label 70,000+ ATTENDEES
      value 4 Days
      desc The world's premier tech conference · Nov 9–12, 2026 · Lisbon, Portugal
      icon people group
    - label WORLD-CLASS SPEAKERS
      value 10+
      desc Sam Altman · Geoffrey Hinton · Ursula von der Leyen · António Guterres · Alexis Ohanian
      icon microphone
    - label STARTUP ECOSYSTEM
      value 5
      desc Startups · Investors · Partners · Media · Attendees — tailored tracks for every role
      icon rocket launch
