<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Web Summit Lisbon 2026 - Infographic</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    html, body { width: 900px; height: 1300px; background: #030318; overflow: hidden; }
    #container { width: 900px; height: 1300px; }
    #export-btn {
      position: fixed; bottom: 20px; right: 20px; z-index: 999;
      padding: 10px 20px; background: #00e5ff; color: #000;
      border: none; border-radius: 6px; cursor: pointer;
      font-weight: bold; font-size: 14px;
    }
  </style>
</head>
<body>
  <div id="container"></div>
  <button id="export-btn">Export SVG</button>
  <script src="/app/vendor/infographic.min.js"></script>
  <script>
    const syntax = `infographic list-grid-badge-card
data
  title WEB SUMMIT LISBON 2026
  desc November 9–12 · Lisbon, Portugal · Where the Future Meets Now
  lists
    - label 2-FOR-1 TICKET DEAL
      value SAVE 50%
      desc 24 HOURS ONLY · Buy one, get one free
      icon ticket
    - label GLOBAL SCALE
      value 70,000+
      desc Attendees from across the world
      icon globe
    - label TOP SPEAKERS
      value 10+
      desc Sam Altman · Geoffrey Hinton · Ursula von der Leyen
      icon microphone
    - label EPIC DURATION
      value 4 Days
      desc Nov 9–12 · Keynotes, networking & deals
      icon calendar
    - label PARTICIPANT TRACKS
      value 5
      desc Startups · Investors · Partners · Media
      icon people group
    - label COMMUNITY VOICES
      value ★★★★★
      desc "Peer into the future" — Brad Smith, Microsoft
      icon star fill
theme
  palette #00e5ff #ff0080 #c084fc #39ff14 #ffdd00 #ff6b35`;

    const infographic = new AntVInfographic.Infographic({
      container: '#container',
      width: '900px',
      height: '1300px',
    });

    infographic.render(syntax);

    document.fonts?.ready.then(() => {
      infographic.render(syntax);
    }).catch((error) => console.error('Error waiting for fonts:', error));

    document.getElementById('export-btn').addEventListener('click', async () => {
      try {
        const svgDataUrl = await infographic.toDataURL({ type: 'svg' });
        const a = document.createElement('a');
        a.href = svgDataUrl;
        a.download = 'web-summit-2026-poster.svg';
        a.click();
      } catch (e) {
        console.error('Export failed:', e);
      }
    });
  </script>
</body>
</html>
